// All the cluster cores are woken up by the bootrom and jump here. Only the
// first hart goes through the OS initialization, the other ones are parked
// until multi-core support is added.

    .global _start
    .type   _start, @function
_start:
    csrr  t0, mhartid
    bnez  t0, __pi_hart_park

    // Stack initialization
    la    x2, stack

    // Work-around to cancel call-stack generated by rom on some architectures
    // to not show it in profiler
    la    t0, _start_call_stack_reset_0
    jr    t0
_start_call_stack_reset_0:

    // Do all other initializations from C code
    la    t0, __pi_init_start
    addi  a0, x0, 0
    jalr  x1, t0

__pi_hart_park:
    wfi
    j     __pi_hart_park

    .size   _start, . - _start
